button.content:
@switch (variant()) {
  @case ('grouped') {
    <sd-section title="Tác vụ gộp bằng popover">
      <div class="p-20 d-flex align-items-center flex-wrap gap-8">
        <sd-button title="Tác vụ" prefixIcon="bolt" suffixIcon="expand_more" type="light" color="primary">
          <sd-button-item-divider title="Xử lý hồ sơ" />
          @for (action of workflowActions; track action.title) {
            <sd-button-item [prefixIcon]="action.icon" [color]="action.color" (click)="runAction(action.title)">{{
              action.title
            }}</sd-button-item>
          }
          <sd-button-item-divider title="Dữ liệu" />
          @for (action of dataActions; track action.title) {
            <sd-button-item [prefixIcon]="action.icon" [color]="action.color" (click)="runAction(action.title)">{{
              action.title
            }}</sd-button-item>
          }
        </sd-button>
        <sd-button prefixIcon="more_horiz" tooltip="Tác vụ khác" type="light" color="secondary">
          @for (action of actions; track action.title) {
            <sd-button-item [prefixIcon]="action.icon" [color]="action.color" (click)="runAction(action.title)">{{
              action.title
            }}</sd-button-item>
          }
        </sd-button>
      </div>
    </sd-section>
  }
  @case ('crud') {
    <sd-section hideHeader
      ><div class="p-20">
        <div class="d-flex align-items-center flex-wrap gap-8">
          <sd-button title="Tạo mới" prefixIcon="add" type="fill" color="primary" routerLink="/pattern/drawer/create" />
          <sd-button title="Chỉnh sửa" prefixIcon="edit" type="fill" color="primary" routerLink="/pattern/drawer/update" />
          <sd-button
            title="Lưu"
            prefixIcon="save"
            type="fill"
            color="primary"
            [loading]="saving()"
            [disabled]="saving()"
            (click)="save()" />
          <sd-button title="Xoá" prefixIcon="delete" type="fill" color="error" [disabled]="deleted()" (click)="remove()" />
        </div>
        <p class="mt-18 mb-0">
          Xem chi tiết qua <a routerLink="/pattern/drawer/detail">LH-1024</a> hoặc
          <a routerLink="/pattern/drawer/detail">Nguyễn Minh Anh</a>.
        </p>
      </div></sd-section
    >
    <p class="text-secondary fs-13">
      Convention khuyến khích khi màn hình đã thể hiện rõ đối tượng. Tạo, sửa và lưu dùng primary fill; xoá dùng error fill.
    </p>
  }
  @case ('crud-entity') {
    <sd-section hideHeader
      ><div class="p-20">
        <div class="d-flex align-items-center flex-wrap gap-8">
          <sd-button title="Tạo liên hệ" prefixIcon="add" type="fill" color="primary" routerLink="/pattern/drawer/create" />
          <sd-button title="Chỉnh sửa liên hệ" prefixIcon="edit" type="fill" color="primary" routerLink="/pattern/drawer/update" />
          <sd-button
            title="Lưu liên hệ"
            prefixIcon="save"
            type="fill"
            color="primary"
            [loading]="saving()"
            [disabled]="saving()"
            (click)="save()" />
        </div>
        <p class="mt-18 mb-0">Chi tiết: <a routerLink="/pattern/drawer/detail">Nguyễn Minh Anh</a></p>
      </div></sd-section
    >
    <p class="text-secondary fs-13">CRUD theo đối tượng: thêm tên đối tượng khi cần phân biệt nhiều ngữ cảnh trong cùng màn hình.</p>
  }
  @case ('query') {
    <sd-section hideHeader
      ><div class="p-20 d-flex align-items-center flex-wrap gap-8">
        <sd-button title="Tìm kiếm" prefixIcon="search" type="light" color="primary" routerLink="/pattern/table/quick-search" />
        <sd-button title="Áp dụng bộ lọc" prefixIcon="filter_alt" type="light" color="info" routerLink="/pattern/table/external-filter" />
        <sd-button
          title="Xóa bộ lọc"
          prefixIcon="filter_alt_off"
          type="light"
          color="secondary"
          (click)="message.set('Đã đặt lại điều kiện tìm kiếm mẫu.')" /></div
    ></sd-section>
  }
  @case ('workflow') {
    <div class="d-grid gap-20">
      <sd-section title="Tác vụ có icon"
        ><div class="p-20 d-flex align-items-center flex-wrap gap-8">
          @for (action of actions; track action.title) {
            <sd-button
              [title]="action.title"
              [prefixIcon]="action.icon"
              [color]="action.color"
              type="light"
              (click)="runAction(action.title)" />
          }</div
      ></sd-section>
      <sd-section title="Tác vụ không icon"
        ><div class="p-20 d-flex align-items-center flex-wrap gap-8">
          @for (action of actions; track action.title) {
            <sd-button [title]="action.title" [color]="action.color" type="light" (click)="runAction(action.title)" />
          }</div
      ></sd-section>
      <sd-section title="Tác vụ nhỏ gọn"
        ><div class="p-20 d-flex align-items-center flex-wrap gap-8">
          @for (action of actions; track action.title) {
            <sd-button
              [prefixIcon]="action.icon"
              [tooltip]="action.title"
              [color]="action.color"
              type="light"
              (click)="runAction(action.title)" />
          }</div
      ></sd-section>
    </div>
    <p class="text-secondary fs-13">
      Màu theo ý nghĩa nghiệp vụ. Icon-only cần tooltip mô tả rõ hành động; dùng khi người dùng đã quen thao tác.
    </p>
  }
  @case ('danger') {
    @if (!deleted()) {
      <p>Đơn hàng mẫu DH-1024 · An Phát</p>
      <sd-button title="Xoá" prefixIcon="delete" color="error" type="fill" (click)="remove()" />
    } @else {
      <sd-button
        title="Khôi phục dữ liệu mẫu"
        prefixIcon="restore"
        type="light"
        color="info"
        (click)="deleted.set(false); message.set('')" />
    }
  }
  @case ('async') {
    <sd-button
      [title]="saving() ? 'Đang lưu…' : attempt() === 1 ? 'Thử lại' : 'Lưu'"
      prefixIcon="save"
      type="fill"
      color="primary"
      [disabled]="saving()"
      [loading]="saving()"
      (click)="save()" />
    <p class="text-secondary fs-13">Lần lưu đầu mô phỏng lỗi; thử lại thành công. Không gửi lặp khi pending.</p>
  }
}
<p role="status">{{ message() }}</p>

import { ChangeDetectionStrategy, Component, DestroyRef, inject, input, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { SdButton, SdButtonItem, SdButtonItemDivider } from '@sdcorejs/angular/components/button';
import { SdSection } from '@sdcorejs/angular/components/section';
import { SdConfirmService } from '@sdcorejs/angular/services/confirm';
@Component({
  selector: 'app-pattern-button',
  imports: [RouterLink, SdButton, SdButtonItem, SdButtonItemDivider, SdSection],
  templateUrl: './button.component.html',
  styleUrl: '../../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ButtonComponent {
  readonly variant = input('crud');
  readonly message = signal('');
  readonly saving = signal(false);
  readonly attempt = signal(0);
  readonly deleted = signal(false);
  readonly actions = [
    { title: 'Gửi duyệt', icon: 'send', color: 'primary' },
    { title: 'Duyệt', icon: 'check_circle', color: 'success' },
    { title: 'Từ chối', icon: 'cancel', color: 'error' },
    { title: 'Tạm dừng', icon: 'pause_circle', color: 'warning' },
    { title: 'Xuất dữ liệu', icon: 'download', color: 'info' },
    { title: 'In', icon: 'print', color: 'secondary' },
  ] as const;
  readonly workflowActions = this.actions.slice(0, 4);
  readonly dataActions = this.actions.slice(4);
  runAction(title: string): void {
    this.message.set('Đã thực hiện tác vụ mẫu: ' + title + '.');
  }
  private readonly confirm = inject(SdConfirmService);
  private readonly destroy = inject(DestroyRef);
  async remove(): Promise<void> {
    const target = this.variant() === 'crud' ? 'liên hệ LH-1024' : 'đơn hàng DH-1024';
    try {
      await this.confirm.confirm('Bản ghi ' + target + ' sẽ bị xoá khỏi danh sách mẫu này.', {
        title: 'Xoá ' + target + '?',
        yesTitle: 'Xoá',
        noTitle: 'Giữ lại',
        yesButtonColor: 'error',
      });
      this.deleted.set(true);
      this.message.set('Đã xoá ' + target + ' trong dữ liệu mẫu.');
    } catch {
      this.message.set('Đã giữ lại bản ghi.');
    }
  }
  async save(): Promise<void> {
    if (this.saving()) return;
    this.saving.set(true);
    this.message.set('');
    await new Promise(r => setTimeout(r, 500));
    if (this.destroy.destroyed) return;
    this.attempt.update(x => x + 1);
    this.saving.set(false);
    this.message.set(
      this.variant() === 'async' && this.attempt() === 1 ? 'Không thể lưu. Dữ liệu được giữ nguyên; vui lòng thử lại.' : 'Đã lưu thay đổi.'
    );
  }
}

:host {
  display: block;
  min-width: 0;
}
.pattern-body {
  padding: 24px;
  min-width: 0;
}
.table-page {
  height: 100%;
  padding: 12px;
  > div,
  .surface {
    height: 100%;
    min-height: 0;
  }
  .surface {
    display: flex;
    flex-direction: column;
  }
  .preview-title {
    flex-shrink: 0;
  }
  sd-tab-group {
    flex: 1;
    min-height: 0;
  }
  .preview-stage {
    height: 100%;
    padding: 12px;
    overflow: hidden;
  }
  ::ng-deep .mat-mdc-tab-group {
    height: 100%;
  }
  ::ng-deep .mat-mdc-tab-body-wrapper {
    flex: 1;
    min-height: 0;
  }
}
.pattern-layout {
  display: grid;
  grid-template-columns: 230px minmax(0, 1fr);
  gap: 24px;
  align-items: start;
}
.pattern-layout > * {
  min-width: 0;
}
.variants {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border: 1px solid var(--sd-border);
  border-radius: 8px;
  background: var(--sd-surface);
}
.variants a {
  padding: 12px;
  color: var(--sd-text);
  text-decoration: none;
  border: 0;
  border-radius: 4px;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.variants a.active {
  color: var(--sd-primary);
  background: var(--sd-primary-light, #edf2ff);
  font-weight: 600;
}
.surface {
  border: 1px solid var(--sd-border);
  border-radius: 8px;
  background: var(--sd-surface);
  overflow: hidden;
  min-width: 0;
}
.preview-title,
.guide {
  padding: 18px 20px;
  border-bottom: 1px solid var(--sd-border);
}
.preview-title {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}
.preview-stage {
  padding: 20px;
  background: var(--sd-background, #f8f9fa);
  min-width: 0;
}
h2 {
  font-size: 18px;
  margin: 0;
}
h3 {
  font-size: 15px;
  margin: 0 0 12px;
}
p {
  margin: 8px 0;
}
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  font-size: 12px;
  border-radius: 4px;
  background: #fff2dc;
  color: #82550c;
  white-space: nowrap;
}
.badge.active {
  background: #eaf0ff;
  color: #254fae;
}
.badge.done {
  background: #e8f4eb;
  color: #256638;
}
.query-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  margin-bottom: 14px;
}
.query-bar .search {
  flex: 1;
  min-width: 200px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 13px;
}
input,
select,
textarea {
  font: inherit;
  min-height: 44px;
  padding: 9px 12px;
  border: 1px solid var(--sd-border);
  border-radius: 5px;
  background: var(--sd-surface);
  color: var(--sd-text);
  min-width: 0;
}
input[type='checkbox'] {
  min-height: 18px;
  width: 18px;
  accent-color: var(--sd-primary);
}
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--sd-primary);
  outline-offset: 3px;
}
.table-region {
  overflow: auto;
  max-width: 100%;
  min-width: 0;
}
.table-region sd-table {
  display: block;
  min-width: 640px;
}
.table-region.fill {
  overflow: hidden;
  ::ng-deep external-filter .sd-external-filter-body .row > div {
    flex: 1 1 180px;
    min-width: 0;
    max-width: 100%;
  }
  sd-table {
    display: flex;
    min-width: 0;
  }
}
.plain-table {
  width: 100%;
  border-collapse: collapse;
  white-space: nowrap;
  background: var(--sd-surface);
}
.plain-table th,
.plain-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--sd-border);
  text-align: left;
}
.plain-table th {
  background: var(--sd-background, #f3f5f7);
  font-size: 12px;
}
.plain-table .number,
.number {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.form-grid.one {
  grid-template-columns: 1fr;
  max-width: 540px;
}
.form-compact {
  width: 100%;
  max-width: 580px;
  box-sizing: border-box;
  margin-inline: auto;
}
.form-grid > * {
  min-width: 0;
}
.span {
  grid-column: 1/-1;
}
.form-shell {
  max-width: 860px;
  margin: auto;
  padding: 20px;
  background: var(--sd-surface);
  border: 1px solid var(--sd-border);
  border-radius: 6px;
}
.contact-form-section {
  max-width: 860px;
  margin-inline: auto;
}
.form-section {
  margin: 0 0 20px;
  padding: 0 0 20px;
  border: 0;
  border-bottom: 1px solid var(--sd-border);
}
.form-section legend {
  font-weight: 600;
  padding-bottom: 14px;
}
.form-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 18px;
  margin-top: 20px;
  border-top: 1px solid var(--sd-border);
  flex-wrap: wrap;
}
.facts {
  display: grid;
  grid-template-columns: minmax(100px, 1fr) 2fr;
  gap: 14px;
  overflow-wrap: anywhere;
}
.facts dt {
  color: var(--sd-text-secondary);
}
.facts dd {
  margin: 0;
}
.card-grid,
.queue {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
.record-card {
  padding: 18px;
  background: var(--sd-surface);
  border: 1px solid var(--sd-border);
  border-radius: 8px;
}
.queue-column {
  padding: 12px;
  background: var(--sd-background, #f1f3f6);
  border: 1px solid var(--sd-border);
  border-radius: 8px;
}
.queue-column .record-card {
  margin: 12px 0;
}
.overview {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.overview > section {
  padding: 20px;
}
.pager {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
  padding: 16px 0;
}
.source-file {
  margin: 16px 0;
}
.tag {
  border: 1px solid var(--sd-border);
  background: var(--sd-surface);
  border-radius: 5px;
  padding: 6px 10px;
  cursor: pointer;
}
@media (max-width: 1000px) {
  .pattern-layout {
    grid-template-columns: 1fr;
  }
  .variants {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .queue,
  .overview {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 600px) {
  .pattern-body,
  .preview-stage {
    padding: 12px;
  }
  .form-grid,
  .card-grid {
    grid-template-columns: 1fr;
  }
  .form-shell {
    padding: 14px;
  }
  .query-bar .search {
    flex-basis: 100%;
  }
  .query-bar .field {
    flex: 1;
  }
  input,
  select {
    font-size: 16px;
  }
  .facts {
    grid-template-columns: 1fr;
    gap: 6px;
  }
  .facts dd {
    margin-bottom: 10px;
  }
}

