import { SdIcon } from '@sdcorejs/angular/modules/icon';
export interface ScoreCard {
  id: string;
  label: string;
  value: string | number;
  hint: string;
  icon?: string;
  tone?: string;
  progress?: number;
}
@Component({
  selector: 'app-pattern-scorecards',
  imports: [SdCard, SdCardGroup, SdSection, SdIcon, NgTemplateOutlet],
  templateUrl: './scorecard-strip.component.html',
  styleUrl: './scorecard-strip.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ScorecardStripComponent {
  readonly cards = input.required<ScoreCard[]>();
  readonly selected = input('');
  readonly interactive = input(false);
  readonly iconLayout = input<'none' | 'inline' | 'tile'>('none');
  readonly compact = input(false);
  readonly selection = output<string>();
  iconColor(card: ScoreCard): string {
    if (card.tone === 'pending') return 'warning';
    if (card.tone === 'done') return 'success';
    if (card.id === 'customers') return 'success';
    if (card.id === 'amount') return 'warning';
    return 'info';
  }
  choose(value: string | string[] | null): void {
    this.selection.emit(typeof value === 'string' ? value : '');
  }
}

export type OrderStatus = 'pending' | 'active' | 'done';
export interface PatternOrder {
  id: number;
  code: string;
  name: string;
  region: string;
  status: OrderStatus;
  amount: number;
  owner: string;
}
export interface PatternQuery {
  search: string;
  status: string;
  region: string;
  sort: string;
}
export const EMPTY_QUERY: PatternQuery = { search: '', status: '', region: '', sort: 'code' };
export const STATUS_LABELS: Record<OrderStatus, string> = { pending: 'Chờ xử lý', active: 'Đang xử lý', done: 'Hoàn tất' };
export const REGIONS = ['Miền Bắc', 'Miền Trung', 'Miền Nam'];
export const normalizeSearch = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase()
    .trim();
export function queryOrders(records: readonly PatternOrder[], query: PatternQuery): PatternOrder[] {
  return records
    .filter(
      row =>
        (!query.status || row.status === query.status) &&
        (!query.region || row.region === query.region) &&
        normalizeSearch(row.code + ' ' + row.name).includes(normalizeSearch(query.search))
    )
    .sort(
      (a, b) => (query.sort === 'amount-desc' ? b.amount - a.amount : query.sort === 'amount-asc' ? a.amount - b.amount : 0) || a.id - b.id
    );
}
export function seedOrders(): PatternOrder[] {
  const names = ['An Phát', 'Minh Long', 'Bình Minh', 'Đại Việt', 'Hải Nam', 'Phú Gia', 'Thiên An', 'Trường Sơn'];
  return Array.from({ length: 24 }, (_, i) => ({
    id: i + 1,
    code: 'DH-' + (1001 + i),
    name: names[i % 8],
    region: REGIONS[Math.floor(i / 3) % 3],
    status: (['pending', 'active', 'done'] as const)[i % 3],
    amount: (i + 2) * 1750000,
    owner: ['Lan', 'Minh', 'Hà', 'Nam'][i % 4],
  }));
}

import { Injectable, signal } from '@angular/core';
import { OrderStatus, seedOrders } from './pattern-query';
@Injectable()
export class PatternStore {
  readonly records = signal(seedOrders());
  readonly pending = signal<number[]>([]);
  readonly message = signal('');
  readonly simulateError = signal(false);
  async transition(ids: number[], status: OrderStatus): Promise<boolean> {
    if (!ids.length || this.pending().length) return false;
    this.pending.set(ids);
    this.message.set('');
    const fail = this.simulateError();
    try {
      await new Promise(resolve => setTimeout(resolve, 350));
      if (fail) throw new Error('Không thể cập nhật. Dữ liệu được giữ nguyên; hãy thử lại.');
      this.records.update(rows => rows.map(row => (ids.includes(row.id) ? { ...row, status } : row)));
      this.message.set('Đã cập nhật ' + ids.length + ' đơn hàng.');
      return true;
    } catch (error) {
      this.message.set((error as Error).message);
      return false;
    } finally {
      this.pending.set([]);
    }
  }
  reset(): void {
    if (!this.pending().length) {
      this.records.set(seedOrders());
      this.message.set('Đã khôi phục dữ liệu mẫu.');
    }
  }
}

import { ChangeDetectionStrategy, Component, OnInit, computed, inject, input, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdDataState } from '@sdcorejs/angular/components/data-state';
import { ScoreCard, ScorecardStripComponent } from '../../components/scorecard-strip.component';
import { QueryBarComponent } from '../../components/query-bar.component';
import { ResultsTableComponent } from '../../components/results-table.component';
import { OrderDetailComponent } from '../../components/order-detail.component';
import { RecordCollectionComponent } from './record-collection.component';
import { PatternStore } from '../../data/pattern-store';
import { EMPTY_QUERY, PatternQuery, STATUS_LABELS, queryOrders } from '../../data/pattern-query';
@Component({
  selector: 'app-pattern-composition',
  imports: [
    FormsModule,
    SdButton,
    SdDataState,
    ScorecardStripComponent,
    QueryBarComponent,
    ResultsTableComponent,
    OrderDetailComponent,
    RecordCollectionComponent,
  ],
  providers: [PatternStore],
  templateUrl: './composition.component.html',
  styleUrl: '../../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CompositionComponent implements OnInit {
  readonly variant = input('listing');
  readonly store = inject(PatternStore);
  readonly view = signal('listing');
  readonly query = signal<PatternQuery>({ ...EMPTY_QUERY });
  readonly page = signal(0);
  readonly pageSize = signal(6);
  readonly state = signal('data');
  readonly labels = STATUS_LABELS;
  readonly statuses = Object.keys(STATUS_LABELS);
  private readonly route = inject(ActivatedRoute);
  readonly records = computed(() => (this.state() === 'empty' ? [] : this.store.records()));
  readonly rows = computed(() => queryOrders(this.records(), this.query()));
  readonly paged = computed(() => this.rows().slice(this.page() * this.pageSize(), (this.page() + 1) * this.pageSize()));
  readonly cards = computed<ScoreCard[]>(() => [
    { id: '', label: 'Tất cả đơn hàng', value: this.records().length, hint: 'Toàn bộ dữ liệu mẫu', icon: 'receipt_long' },
    ...Object.entries(STATUS_LABELS).map(([id, label]) => ({
      id,
      label,
      value: this.records().filter(r => r.status === id).length,
      hint: 'Chọn để lọc',
      icon: id === 'pending' ? 'schedule' : id === 'active' ? 'sync' : 'check_circle',
      tone: id,
    })),
  ]);
  readonly metrics = computed<ScoreCard[]>(() => {
    const rows = this.records(),
      done = rows.filter(r => r.status === 'done').length;
    return [
      {
        id: 'amount',
        label: 'Tổng giá trị',
        value: rows.reduce((s, r) => s + r.amount, 0) / 1000000 + ' triệu ₫',
        hint: 'Toàn bộ đơn hàng mẫu',
        icon: 'payments',
      },
      {
        id: 'progress',
        label: 'Tỷ lệ hoàn tất',
        value: (rows.length ? Math.round((done / rows.length) * 100) : 0) + '%',
        hint: done + ' / ' + rows.length + ' đơn hàng',
        icon: 'check_circle',
        progress: rows.length ? (done / rows.length) * 100 : 0,
      },
    ];
  });
  readonly attention = computed(() =>
    this.records()
      .filter(r => r.status === 'pending')
      .sort((a, b) => b.amount - a.amount)
      .slice(0, 4)
  );
  ngOnInit(): void {
    this.view.set(this.variant());
    const status = this.route.snapshot.queryParamMap.get('status');
    if (status && this.statuses.includes(status)) this.change({ ...EMPTY_QUERY, status });
  }
  change(query: PatternQuery): void {
    this.query.set(query);
    this.page.set(0);
  }
  select(status: string): void {
    this.change({ ...this.query(), status });
  }
  drill(status: string): void {
    this.change({ ...EMPTY_QUERY, status });
    this.view.set('listing');
  }
  setView(view: string): void {
    this.view.set(view);
    this.page.set(0);
  }
  count(status: string): number {
    return this.records().filter(r => r.status === status).length;
  }
}

