import { ChangeDetectionStrategy, Component, input } from '@angular/core';
import { SdSection, SdSectionItem } from '@sdcorejs/angular/components/section';
import { ContactRecord } from './form-editor.component';
@Component({
  selector: 'app-pattern-contact-facts',
  imports: [SdSection, SdSectionItem],
  template: `<sd-section hideHeader>
    <sd-section-item label="Họ và tên" labelWidth="35%"
      ><strong>{{ record().name }}</strong></sd-section-item
    >
    <sd-section-item label="Email" labelWidth="35%"
      ><strong>{{ record().email }}</strong></sd-section-item
    >
    <sd-section-item label="Điện thoại" labelWidth="35%"
      ><strong>{{ record().phone || 'Chưa cung cấp' }}</strong></sd-section-item
    >
    <sd-section-item label="Khu vực" labelWidth="35%"
      ><strong>{{ record().region || 'Chưa cung cấp' }}</strong></sd-section-item
    >
    <sd-section-item label="Ghi chú" labelWidth="35%"
      ><strong>{{ record().note || 'Chưa cung cấp' }}</strong></sd-section-item
    >
  </sd-section>`,
  styles: ':host { display: block; min-width: 0; overflow-wrap: anywhere; }',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ContactFactsComponent {
  readonly record = input.required<ContactRecord>();
}

@if (errorMessage()) {
  <sd-inform class="d-block mb-16" [color]="errorColor()" title="Chưa thể lưu thông tin" [description]="errorMessage()" />
}
@if (layout() === 'section-errors') {
  <form class="d-grid gap-16" (submit)="$event.preventDefault(); save()" novalidate>
    <sd-section title="Thông tin cơ bản">
      <div class="p-20">
        @if (sectionWarnings().identity) {
          <sd-inform class="d-block mb-16" color="warning" title="Kiểm tra thông tin cơ bản" description="Vui lòng nhập họ và tên." />
        }
        <sd-input name="name" label="Họ và tên" [form]="form" [model]="initial().name" required />
      </div>
    </sd-section>
    <sd-section title="Thông tin liên lạc">
      <div class="p-20">
        @if (sectionWarnings().communication) {
          <sd-inform class="d-block mb-16" color="warning" title="Kiểm tra thông tin liên lạc" description="Vui lòng nhập email hợp lệ." />
        }
        <div class="form-grid">
          <sd-input name="email" label="Email" type="email" pattern="EMAIL" [form]="form" [model]="initial().email" required />
          <sd-input name="phone" label="Số điện thoại" [form]="form" [model]="initial().phone" />
        </div>
      </div>
    </sd-section>
    <sd-section title="Thông tin bổ sung">
      <div class="p-20 form-grid">
        <sd-select
          name="region"
          label="Khu vực"
          [form]="form"
          [model]="initial().region"
          [items]="regions"
          valueField="id"
          displayField="name" />
        <sd-textarea name="note" label="Ghi chú" [form]="form" [model]="initial().note" />
      </div>
    </sd-section>
  </form>
} @else {
  <sd-section hideHeader class="contact-form-section">
    <form class="p-20" [class.form-compact]="layout() === 'simple'" (submit)="$event.preventDefault(); save()" novalidate>
      @if (layout() === 'sections') {
        <h3>Thông tin liên hệ</h3>
        <p class="text-secondary fs-13">Đầu mối chính để phối hợp công việc.</p>
      }
      <div class="form-grid" [class.one]="layout() === 'simple'">
        <sd-input name="name" label="Họ và tên" [form]="form" [model]="initial().name" [maxlength]="100" required />
        <sd-input name="email" label="Email" type="email" pattern="EMAIL" [form]="form" [model]="initial().email" required />
        <sd-input name="phone" label="Số điện thoại" [form]="form" [model]="initial().phone" />
        <sd-select
          name="region"
          label="Khu vực"
          [form]="form"
          [model]="initial().region"
          [items]="regions"
          valueField="id"
          displayField="name" />
      </div>
      @if (layout() === 'sections') {
        <div class="mt-22">
          <h3>Thông tin bổ sung</h3>
          <sd-textarea name="note" label="Ghi chú phối hợp" [form]="form" [model]="initial().note" />
        </div>
      }
      @if (message()) {
        <p role="status">{{ message() }}</p>
      }
      @if (!hideFooter()) {
        <div class="form-footer">
          <sd-button title="Hủy" type="outline" [disabled]="saving()" (click)="cancel()" /><sd-button
            [title]="saving() ? 'Đang lưu…' : mode() === 'update' ? 'Lưu thay đổi' : 'Tạo liên hệ'"
            type="fill"
            color="primary"
            [loading]="saving()"
            [disabled]="saving()"
            (click)="save()" />
        </div>
      }
    </form>
  </sd-section>
}

import { ChangeDetectionStrategy, Component, DestroyRef, OnInit, computed, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdSection } from '@sdcorejs/angular/components/section';
import { SdInform } from '@sdcorejs/angular/components/inform';
import { SdInput } from '@sdcorejs/angular/forms/input';
import { SdSelect } from '@sdcorejs/angular/forms/select';
import { SdTextarea } from '@sdcorejs/angular/forms/textarea';
import { PatternDraft } from '../data/pattern-draft';
import { SdNotifyService } from '@sdcorejs/angular/services/notify';
import { REGIONS } from '../data/pattern-query';

export interface ContactRecord {
  name: string;
  email: string;
  phone: string;
  region: string;
  note: string;
}
export const emptyContact = (): ContactRecord => ({ name: '', email: '', phone: '', region: REGIONS[0], note: '' });
export const sampleContact = (): ContactRecord => ({
  name: 'Nguyễn Minh Anh',
  email: 'minhanh@example.test',
  phone: '0900000000',
  region: REGIONS[0],
  note: 'Đầu mối phối hợp',
});
@Component({
  selector: 'app-pattern-form-editor',
  imports: [ReactiveFormsModule, SdButton, SdSection, SdInform, SdInput, SdSelect, SdTextarea],
  templateUrl: './form-editor.component.html',
  styleUrl: '../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class FormEditorComponent implements OnInit {
  readonly layout = input('simple');
  readonly mode = input('create');
  readonly initial = input<ContactRecord>(emptyContact());
  readonly hideFooter = input(false);
  readonly errorPresentation = input<'notify' | 'inform'>('notify');
  readonly saved = output<ContactRecord>();
  readonly cancelled = output<void>();
  readonly saving = signal(false);
  readonly message = signal('');
  readonly attempted = signal(false);
  readonly errorMessage = signal('');
  readonly errorColor = signal<'warning' | 'error'>('warning');
  readonly sectionWarnings = computed(() => {
    this.revision();
    return {
      identity: this.attempted() && !!this.form.get('name')?.invalid,
      communication: this.attempted() && !!this.form.get('email')?.invalid,
    };
  });
  readonly revision = signal(0);
  private baseline = '';
  // Core fields register and validate their own controls on this group.
  readonly form = new FormGroup<Record<string, FormControl>>({});
  readonly regions = REGIONS.map(name => ({ id: name, name }));
  readonly dirty = computed(() => {
    this.revision();
    return this.snapshot() !== this.baseline;
  });
  private readonly draft = inject(PatternDraft);
  private readonly notify = inject(SdNotifyService);
  private readonly destroy = inject(DestroyRef);
  ngOnInit(): void {
    this.baseline = this.snapshot();
    this.revision.update(n => n + 1);
    const subscription = this.form.valueChanges.subscribe(() => this.revision.update(n => n + 1));
    const dirty = () => this.dirty(),
      saving = () => this.saving();
    this.draft.dirty = dirty;
    this.draft.saving = saving;
    this.destroy.onDestroy(() => {
      subscription.unsubscribe();
      if (this.draft.dirty === dirty) {
        this.draft.dirty = () => false;
        this.draft.saving = () => false;
      }
    });
  }
  private snapshot(): string {
    return JSON.stringify(this.readContact());
  }
  private readContact(): ContactRecord {
    const value = this.form.getRawValue();
    const initial = this.initial();
    const field = (key: keyof ContactRecord): string => (key in value ? (value[key] ?? '') : initial[key]);
    // Stable order/defaults also cover layouts that do not render every field.
    return {
      name: field('name'),
      email: field('email'),
      phone: field('phone'),
      region: field('region'),
      note: field('note'),
    };
  }
  async save(): Promise<boolean> {
    if (this.saving()) return false;
    this.message.set('');
    this.errorMessage.set('');
    this.attempted.set(true);
    this.form.markAllAsTouched();
    const invalid = this.form.invalid;
    if (invalid) {
      const message = 'Kiểm tra họ và tên, email hợp lệ trước khi lưu.';
      this.errorColor.set('warning');
      if (this.errorPresentation() === 'inform') {
        if (this.layout() !== 'section-errors') this.errorMessage.set(message);
      } else this.notify.warning(message);
      return false;
    }
    this.saving.set(true);
    this.message.set('');
    this.form.disable();
    await new Promise(resolve => setTimeout(resolve, 450));
    if (this.destroy.destroyed) return false;
    this.form.enable();
    this.saving.set(false);
    // Phản hồi BE mẫu: email của liên hệ có sẵn bị trùng khi tạo mới.
    if (this.mode() === 'create' && this.readContact().email.trim().toLowerCase() === sampleContact().email) {
      const message = 'Email đã được sử dụng bởi một liên hệ khác. Vui lòng nhập email khác.';
      this.errorColor.set('error');
      if (this.errorPresentation() === 'inform') this.errorMessage.set(message);
      else this.notify.error(message);
      return false;
    }
    this.baseline = this.snapshot();
    this.revision.update(n => n + 1);
    this.message.set('Đã lưu dữ liệu mẫu trong phiên.');
    this.saved.emit(this.readContact());
    return true;
  }
  async cancel(): Promise<void> {
    if (await this.draft.canLeave()) {
      this.form.patchValue(this.initial());
      this.baseline = this.snapshot();
      this.revision.update(n => n + 1);
      this.attempted.set(false);
      this.errorMessage.set('');
      this.message.set('');
      this.cancelled.emit();
    }
  }
}

import { Injectable, inject } from '@angular/core';
import { SdConfirmService } from '@sdcorejs/angular/services/confirm';
@Injectable()
export class PatternDraft {
  private readonly confirm = inject(SdConfirmService);
  dirty: () => boolean = () => false;
  saving: () => boolean = () => false;
  async canLeave(): Promise<boolean> {
    if (this.saving()) return false;
    if (!this.dirty()) return true;
    try {
      await this.confirm.confirm('Bỏ thay đổi sẽ mất nội dung vừa nhập.', {
        title: 'Thông tin chưa được lưu',
        yesTitle: 'Bỏ thay đổi',
        noTitle: 'Tiếp tục chỉnh sửa',
      });
      return true;
    } catch {
      return false;
    }
  }
}

export type OrderStatus = 'pending' | 'active' | 'done';
export interface PatternOrder {
  id: number;
  code: string;
  name: string;
  region: string;
  status: OrderStatus;
  amount: number;
  owner: string;
}
export interface PatternQuery {
  search: string;
  status: string;
  region: string;
  sort: string;
}
export const EMPTY_QUERY: PatternQuery = { search: '', status: '', region: '', sort: 'code' };
export const STATUS_LABELS: Record<OrderStatus, string> = { pending: 'Chờ xử lý', active: 'Đang xử lý', done: 'Hoàn tất' };
export const REGIONS = ['Miền Bắc', 'Miền Trung', 'Miền Nam'];
export const normalizeSearch = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase()
    .trim();
export function queryOrders(records: readonly PatternOrder[], query: PatternQuery): PatternOrder[] {
  return records
    .filter(
      row =>
        (!query.status || row.status === query.status) &&
        (!query.region || row.region === query.region) &&
        normalizeSearch(row.code + ' ' + row.name).includes(normalizeSearch(query.search))
    )
    .sort(
      (a, b) => (query.sort === 'amount-desc' ? b.amount - a.amount : query.sort === 'amount-asc' ? a.amount - b.amount : 0) || a.id - b.id
    );
}
export function seedOrders(): PatternOrder[] {
  const names = ['An Phát', 'Minh Long', 'Bình Minh', 'Đại Việt', 'Hải Nam', 'Phú Gia', 'Thiên An', 'Trường Sơn'];
  return Array.from({ length: 24 }, (_, i) => ({
    id: i + 1,
    code: 'DH-' + (1001 + i),
    name: names[i % 8],
    region: REGIONS[Math.floor(i / 3) % 3],
    status: (['pending', 'active', 'done'] as const)[i % 3],
    amount: (i + 2) * 1750000,
    owner: ['Lan', 'Minh', 'Hà', 'Nam'][i % 4],
  }));
}

@if (variant() === 'lines') {
  <app-pattern-inline-table variant="order-lines" />
} @else if (variant() === 'time-slots') {
  <app-pattern-time-slots />
} @else if (variant() === 'readonly' && !editing()) {
  <section class="form-shell">
    <h3>Thông tin liên hệ</h3>
    <app-pattern-contact-facts [record]="record()" />
    @if (canEdit()) {
      <div class="form-footer"><sd-button title="Chỉnh sửa" prefixIcon="edit" type="fill" color="primary" (click)="edit()" /></div>
    }
  </section>
} @else {
  <app-pattern-form-editor
    [layout]="variant() === 'readonly' ? 'sections' : variant()"
    [mode]="editing() ? 'update' : 'create'"
    [initial]="editing() ? record() : { name: '', email: '', phone: '', region: 'Miền Bắc', note: '' }"
    (saved)="record.set($event); editing.set(false)"
    (cancelled)="editing.set(false)" />
}

import { SdPermissionService } from '@sdcorejs/angular/modules/permission';
import { ChangeDetectionStrategy, Component, inject, input, signal } from '@angular/core';
import { FormEditorComponent, sampleContact } from '../../components/form-editor.component';
import { ContactFactsComponent } from '../../components/contact-facts.component';
import { SdButton } from '@sdcorejs/angular/components/button';
import { InlineTableComponent } from '../table/inline-table.component';
import { TimeSlotsComponent } from './time-slots.component';
@Component({
  selector: 'app-pattern-form',
  imports: [FormEditorComponent, ContactFactsComponent, SdButton, InlineTableComponent, TimeSlotsComponent],
  templateUrl: './form.component.html',
  styleUrl: '../../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class FormComponent {
  private readonly permission = inject(SdPermissionService);
  readonly canEdit = () => this.permission.hasPermission('CRM_CONTACT_C_UPDATE');
  edit(): void {
    if (!this.canEdit()) return;
    this.editing.set(true);
  }
  readonly variant = input('simple');
  readonly record = signal(sampleContact());
  readonly editing = signal(false);
}

import { ChangeDetectionStrategy, Component, DestroyRef, inject, signal } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { SdTime } from '@sdcorejs/angular/forms/time';
import { SdSection } from '@sdcorejs/angular/components/section';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdInform } from '@sdcorejs/angular/components/inform';
import { PatternDraft } from '../../data/pattern-draft';

@Component({
  selector: 'app-pattern-time-slots',
  imports: [SdTime, SdSection, SdButton, SdInform],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <sd-section title="Khung giờ tiếp nhận">
      <div class="slots-content">
        <p class="text-secondary m-0">Chọn giờ bắt đầu và kết thúc cho từng khung trong ngày.</p>
        @if (message()) {
          <sd-inform [color]="saved() ? 'success' : 'warning'" [description]="message()" />
        }
        <div class="slots-grid">
          <strong>Giờ bắt đầu</strong><strong>Giờ kết thúc</strong><span></span>
          @for (row of rows(); track row.id) {
            <sd-time
              name="start"
              [form]="row.form"
              [model]="row.start"
              [ariaLabel]="'Giờ bắt đầu dòng ' + row.id"
              size="sm"
              hideInlineError
              required />
            <sd-time
              name="end"
              [form]="row.form"
              [model]="row.end"
              [ariaLabel]="'Giờ kết thúc dòng ' + row.id"
              size="sm"
              hideInlineError
              required />
            <sd-button
              prefixIcon="delete"
              type="text"
              color="error"
              size="sm"
              [tooltip]="'Xoá khung giờ ' + row.id"
              (click)="remove(row.id)" />
          }
        </div>
        <div><sd-button title="Thêm khung giờ" prefixIcon="add" type="light" color="primary" size="sm" (click)="add()" /></div>
        <div class="d-flex justify-content-end">
          <sd-button title="Lưu khung giờ" prefixIcon="save" type="fill" color="primary" (click)="save()" />
        </div>
      </div>
    </sd-section>
  `,
  styles: `
    :host {
      display: block;
      max-width: 760px;
      margin-inline: auto;
    }
    .slots-content {
      padding: 16px;
      display: grid;
      gap: 16px;
    }
    .slots-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 32px;
      align-items: center;
      gap: 12px;
    }
    .slots-grid strong {
      font-size: 13px;
    }
    sd-time {
      min-width: 0;
    }
    @media (max-width: 480px) {
      .slots-grid {
        gap: 8px;
      }
      .slots-content {
        padding: 12px;
      }
    }
  `,
})
export class TimeSlotsComponent {
  private nextId = 1;
  readonly rows = signal([this.row('08:00', '12:00'), this.row('13:00', '17:00')]);
  readonly message = signal('');
  readonly saved = signal(false);
  private baseline = this.snapshot();
  constructor() {
    const draft = inject(PatternDraft);
    const dirty = () => this.snapshot() !== this.baseline;
    draft.dirty = dirty;
    inject(DestroyRef).onDestroy(() => {
      if (draft.dirty === dirty) draft.dirty = () => false;
    });
  }
  private row(start = '', end = '') {
    return { id: this.nextId++, start, end, form: new FormGroup<Record<string, FormControl>>({}) };
  }
  private snapshot() {
    return JSON.stringify(
      this.rows().map(row => ({
        id: row.id,
        start: row.form.get('start') ? (row.form.get('start')!.value ?? '') : row.start,
        end: row.form.get('end') ? (row.form.get('end')!.value ?? '') : row.end,
      }))
    );
  }
  add() {
    this.rows.update(rows => [...rows, this.row()]);
    this.message.set('');
  }
  remove(id: number) {
    this.rows.update(rows => rows.filter(row => row.id !== id));
    this.message.set('');
  }
  save() {
    this.saved.set(false);
    const intervals: { start: string; end: string }[] = [];
    for (const row of this.rows()) {
      row.form.markAllAsTouched();
      const { start, end } = row.form.getRawValue();
      if (row.form.invalid || !start || !end || start >= end) {
        this.message.set('Điền đủ giờ hợp lệ; giờ kết thúc phải sau giờ bắt đầu trong cùng ngày.');
        return;
      }
      intervals.push({ start, end });
    }
    intervals.sort((a, b) => a.start.localeCompare(b.start));
    if (!intervals.length) {
      this.message.set('Thêm ít nhất một khung giờ.');
      return;
    }
    if (intervals.some((row, i) => i > 0 && row.start < intervals[i - 1].end)) {
      this.message.set('Các khung giờ không được chồng nhau.');
      return;
    }
    this.baseline = this.snapshot();
    this.saved.set(true);
    this.message.set('Đã lưu khung giờ trong phiên mẫu.');
  }
}

:host {
