} @else {
  <div class="d-grid gap-20">
    <sd-section>
      <div sdHeaderLeft>
        <h3>Thông tin liên hệ</h3>
        <p class="text-secondary fs-13 m-0 mt-4">Đầu mối giao nhận của khách hàng</p>
      </div>
      <div sdHeaderRight class="d-flex align-items-center flex-wrap gap-8 justify-content-end">
        <sd-button title="Làm mới" prefixIcon="refresh" type="text" [disabled]="pending()['section']" (click)="act('section', 'Làm mới')" />
        <sd-button title="Import" prefixIcon="upload" type="outline" [disabled]="pending()['section']" (click)="act('section', 'Import')" />
        <sd-button
          title="Thêm liên hệ"
          prefixIcon="add"
