import { ChangeDetectionStrategy, Component, TemplateRef, computed, effect, input, output, viewChild } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import {
  SdTable,
  SdTableCellDefDirective,
  SdTableTitleDefDirective,
  SdTableQuickSearchRightDefDirective,
  SdTableOption,
} from '@sdcorejs/angular/components/table';
import { SdFormatNumberPipe } from '@sdcorejs/angular/pipes';
import { normalizeSearch, PatternOrder, STATUS_LABELS } from '../data/pattern-query';
@Component({
  selector: 'app-pattern-results',
  imports: [
    SdTable,
    SdTableCellDefDirective,
    SdTableTitleDefDirective,
    SdTableQuickSearchRightDefDirective,
    NgTemplateOutlet,
    SdFormatNumberPipe,
  ],
  templateUrl: './results-table.component.html',
  styleUrl: '../styles/pattern.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ResultsTableComponent {
  readonly table = viewChild(SdTable);
  constructor() {
    effect(onCleanup => {
      const table = this.table();
      const paginator = table?.paginator();
      if (!table || !paginator) return;
      // The view query resolves before Core applies its configured initial size.
      let pageSize = this.option().paginate?.pageSize ?? 6;
      const subscription = paginator.page.subscribe(event => {
        // Flush Core's pending initial filter notification without resetting this page.
        table.onFilterCommit();
        if (pageSize === event.pageSize) return;
        pageSize = event.pageSize;
        table.onClearSelection();
        paginator.firstPage();
      });
      onCleanup(() => subscription.unsubscribe());
    });
    effect(onCleanup => {
      const table = this.table();
      const sort = table?.sort();
      const paginator = table?.paginator();
      if (!table || !sort || !paginator) return;
      const subscription = sort.sortChange.subscribe(() => {
        table.onClearSelection();
        table.onFilterCommit();
        paginator.firstPage();
      });
      onCleanup(() => subscription.unsubscribe());
    });
  }
  readonly rows = input.required<PatternOrder[]>();
  readonly selectable = input(false);
  readonly quickSearch = input(false);
  readonly quickSearchRight = input<TemplateRef<unknown>>();
  readonly externalFilter = input(false);
  readonly inlineFilter = input(false);
  readonly filterOperators = input(false);
  readonly groupedActions = input(false);
  readonly customCells = input(false);
  readonly fill = input(false);
  readonly openRecord = output<PatternOrder>();
  readonly approve = output<number[]>();
  readonly complete = output<number[]>();
  readonly option = computed<SdTableOption<PatternOrder>>(() => {
    const rows = this.rows();
    return {
      ...(this.externalFilter() || this.filterOperators()
        ? {
            type: 'server' as const,
            items: async request => {
              await new Promise(resolve => setTimeout(resolve, 1000 + Math.floor(Math.random() * 1001)));
              const name = normalizeSearch(String(request.rawExternalFilter['name'] ?? ''));
              const status = request.rawExternalFilter['status'];
              const filtered = rows.filter(row => {
                if (!normalizeSearch(row.name).includes(name) || (status && row.status !== status)) return false;
                if (!this.filterOperators()) return true;
                // Demo server adapter: Core sends the selected operator with each column filter.
                return ['code', 'name', 'region', 'status', 'amount'].every(field => {
                  const value = request.rawColumnFilter[field];
                  if (value == null || value === '') return true;
                  const actual = row[field as keyof PatternOrder];
                  const operator = request.columnOperator?.[field] ?? (field === 'amount' || field === 'status' ? 'EQUAL' : 'CONTAIN');
                  if (field === 'amount') {
                    const left = Number(actual),
                      right = Number(value);
                    switch (operator) {
                      case 'GREATER_THAN':
                        return left > right;
                      case 'GREATER_OR_EQUAL':
                        return left >= right;
                      case 'LESS_THAN':
                        return left < right;
                      case 'LESS_OR_EQUAL':
                        return left <= right;
                      default:
                        return left === right;
                    }
                  }
                  const left = normalizeSearch(String(actual)),
                    right = normalizeSearch(String(value));
                  return operator === 'EQUAL' ? left === right : operator === 'START_WITH' ? left.startsWith(right) : left.includes(right);
                });
              });
              const field = request.orderBy;
              if (field && ['code', 'name', 'amount'].includes(field) && request.orderDirection) {
                filtered.sort((a, b) => {
                  const left = a[field as keyof PatternOrder];
                  const right = b[field as keyof PatternOrder];
                  const comparison =
                    typeof left === 'number' && typeof right === 'number' ? left - right : String(left).localeCompare(String(right), 'vi');
                  return request.orderDirection === 'DESC' ? -comparison : comparison;
                });
              }
              const start = request.pageNumber * request.pageSize;
              return { items: filtered.slice(start, start + request.pageSize), total: filtered.length };
            },
          }
        : { type: 'local' as const, items: () => rows }),
      rowKey: 'id',
      sort: { enable: true },
      columns: [
        { field: 'code', title: 'Mã đơn', type: 'string', width: '120px', sortable: true },
        {
          field: 'name',
          title: 'Khách hàng',
          type: 'string',
          width: this.filterOperators() ? '240px' : '180px',
          sortable: true,
          filter: this.filterOperators() ? { operator: { enable: true, list: ['CONTAIN', 'EQUAL', 'START_WITH'] } } : undefined,
        },
        { field: 'region', title: 'Khu vực', type: 'string', width: '120px' },
        {
          field: 'status',
          title: 'Trạng thái',
          type: 'values',
          width: '150px',
          option: { items: Object.entries(STATUS_LABELS).map(([id, name]) => ({ id, name })), valueField: 'id', displayField: 'name' },
          useBadge: (_value, row) => ({
            title: STATUS_LABELS[row.status],
            color: row.status === 'pending' ? 'warning' : row.status === 'done' ? 'success' : 'info',
          }),
        },
        {
          field: 'amount',
          title: 'Giá trị (VND)',
          type: 'number',
          align: 'right',
          width: this.filterOperators() ? '240px' : '150px',
          sortable: true,
          filter: this.filterOperators()
            ? {
                operator: {
                  enable: true,
                  list: ['EQUAL', 'GREATER_THAN', 'GREATER_OR_EQUAL', 'LESS_THAN', 'LESS_OR_EQUAL'],
                },
              }
            : undefined,
        },
      ],
      paginate: { pageSize: 6, pages: [6, 12, 24] },
      config: { visible: true },
      filter: {
        cacheable: false,
        hideInlineFilter: !this.inlineFilter(),
        hideExternalFilterToolbar: !this.externalFilter(),
        ...(this.externalFilter()
          ? {
              externalFilters: [
                { field: 'name', title: 'Khách hàng', type: 'string' as const, defaultShowing: true },
                {
                  field: 'status',
                  title: 'Trạng thái',
                  type: 'values' as const,
                  defaultShowing: true,
                  option: {
                    items: Object.entries(STATUS_LABELS).map(([id, name]) => ({ id, name })),
                    valueField: 'id',
                    displayField: 'name',
                  },
                },
              ],
            }
          : this.quickSearch()
            ? { quickSearch: { containFields: ['code', 'name'], placeholder: 'Tìm mã hoặc tên' } }
            : {}),
      },
      ...(this.groupedActions()
        ? {
            command: {
              commands: [
                {
                  title: 'Xử lý đơn hàng',
                  icon: 'more_horiz',
                  children: [
                    { title: 'Xem chi tiết', icon: 'visibility', click: (row: PatternOrder) => this.openRecord.emit(row) },
                    {
                      title: 'Duyệt đơn hàng',
                      icon: 'task_alt',
                      color: 'success' as const,
                      click: (row: PatternOrder) => this.approve.emit([row.id]),
                    },
                    {
                      title: 'Hoàn tất đơn hàng',
                      icon: 'done_all',
                      color: 'info' as const,
                      click: (row: PatternOrder) => this.complete.emit([row.id]),
                    },
                  ],
                },
              ],
            },
          }
        : {}),
      ...(this.selectable() || this.groupedActions()
        ? {
            selector: {
              visible: true,
              actions: this.groupedActions()
                ? [
                    {
                      title: 'Xử lý các đơn đã chọn',
                      icon: 'task_alt',
                      color: 'success',
                      type: 'light',
                      children: [
                        {
                          title: 'Duyệt đơn hàng',
                          icon: 'task_alt',
                          color: 'success',
                          click: selected => this.approve.emit((selected ?? []).map(row => row.id)),
                        },
                        {
                          title: 'Hoàn tất đơn hàng',
                          icon: 'done_all',
                          color: 'info',
                          click: selected => this.complete.emit((selected ?? []).map(row => row.id)),
                        },
                      ],
                    },
                  ]
                : [
                    {
                      title: 'Duyệt đơn hàng',
                      icon: 'task_alt',
                      color: 'success',
                      type: 'light',
                      click: (selected: PatternOrder[]) => this.approve.emit(selected.map(r => r.id)),
                    },
                  ],
            },
          }
        : {}),
    };
  });
}

export type OrderStatus = 'pending' | 'active' | 'done';
export interface PatternOrder {
  id: number;
  code: string;
  name: string;
  region: string;
  status: OrderStatus;
  amount: number;
  owner: string;
}
export interface PatternQuery {
  search: string;
  status: string;
  region: string;
  sort: string;
}
export const EMPTY_QUERY: PatternQuery = { search: '', status: '', region: '', sort: 'code' };
export const STATUS_LABELS: Record<OrderStatus, string> = { pending: 'Chờ xử lý', active: 'Đang xử lý', done: 'Hoàn tất' };
export const REGIONS = ['Miền Bắc', 'Miền Trung', 'Miền Nam'];
export const normalizeSearch = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase()
    .trim();
export function queryOrders(records: readonly PatternOrder[], query: PatternQuery): PatternOrder[] {
  return records
    .filter(
      row =>
        (!query.status || row.status === query.status) &&
        (!query.region || row.region === query.region) &&
        normalizeSearch(row.code + ' ' + row.name).includes(normalizeSearch(query.search))
    )
    .sort(
      (a, b) => (query.sort === 'amount-desc' ? b.amount - a.amount : query.sort === 'amount-asc' ? a.amount - b.amount : 0) || a.id - b.id
    );
}
export function seedOrders(): PatternOrder[] {
  const names = ['An Phát', 'Minh Long', 'Bình Minh', 'Đại Việt', 'Hải Nam', 'Phú Gia', 'Thiên An', 'Trường Sơn'];
  return Array.from({ length: 24 }, (_, i) => ({
    id: i + 1,
    code: 'DH-' + (1001 + i),
    name: names[i % 8],
    region: REGIONS[Math.floor(i / 3) % 3],
    status: (['pending', 'active', 'done'] as const)[i % 3],
    amount: (i + 2) * 1750000,
    owner: ['Lan', 'Minh', 'Hà', 'Nam'][i % 4],
  }));
}

import { ChangeDetectionStrategy, Component, computed, inject, input, signal } from '@angular/core';
import { SdTab, SdTabGroup } from '@sdcorejs/angular/components/tab';
import { SdSection, SdSectionItem } from '@sdcorejs/angular/components/section';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdDataState } from '@sdcorejs/angular/components/data-state';
import { SdInput } from '@sdcorejs/angular/forms/input';
import { SdSelect } from '@sdcorejs/angular/forms/select';
import { SdNotifyService } from '@sdcorejs/angular/services/notify';
import { ResultsTableComponent } from '../../components/results-table.component';
import { seedOrders } from '../../data/pattern-query';

@Component({
  selector: 'app-pattern-tab-group',
  imports: [SdTab, SdTabGroup, SdSection, SdSectionItem, SdButton, SdDataState, SdInput, SdSelect, ResultsTableComponent],
  templateUrl: './tab-group.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: 'd-block' },
})
export class TabGroupComponent {
  tabIcon(label: string): string {
    if (label.startsWith('CUS-')) return 'business';
    return (
      (
        {
          'Thông tin chung': 'info',
          'Tổng quan': 'dashboard',
          'Thông tin liên hệ': 'contacts',
          'Liên hệ': 'mail',
          'Đơn hàng': 'receipt_long',
          'Lịch sử': 'history',
          'Hợp đồng': 'description',
          'Địa chỉ giao hàng': 'location_on',
          'Công nợ': 'account_balance',
          'Thanh toán': 'payments',
          'Tài liệu': 'folder',
          'Cấu hình': 'settings',
          'Tất cả': 'list_alt',
          'Chờ xử lý': 'schedule',
          'Hoàn tất': 'check_circle',
          Bảng: 'table_chart',
          Thẻ: 'view_module',
        } as Record<string, string>
      )[label] ?? 'info'
    );
  }
  readonly variant = input('basic');
  readonly notify = inject(SdNotifyService);
  readonly selected = signal(0);
  readonly rows = signal(seedOrders());
  readonly shape = signal<'line' | 'pills' | 'segmented'>('line');
  readonly shapeOptions = [
    { id: 'line', name: 'Line · Gạch chân' },
    { id: 'pills', name: 'Pills · Bo tròn' },
    { id: 'segmented', name: 'Segmented · Chia nhóm' },
  ];
  readonly loading = signal(false);
  readonly state = signal<'ready' | 'empty' | 'error'>('ready');
  readonly available = signal(false);
  readonly records = signal(['CUS-001', 'CUS-002', 'CUS-003']);
  readonly names: Record<string, string> = { 'CUS-001': 'Công ty An Phát', 'CUS-002': 'Công ty Minh Long', 'CUS-003': 'Công ty Bình Minh' };
  readonly recordDrafts: Record<string, string> = { ...this.names };
  name = 'Công ty An Phát';
  email = 'contact@anphat.example';
  readonly labels = computed(() => {
    switch (this.variant()) {
      case 'many':
        return [
          'Tổng quan',
          'Thông tin liên hệ',
          'Đơn hàng',
          'Hợp đồng',
          'Địa chỉ giao hàng',
          'Công nợ',
          'Thanh toán',
          'Tài liệu',
          'Lịch sử',
          'Cấu hình',
        ];
      case 'counts':
        return ['Tất cả', 'Chờ xử lý', 'Hoàn tất'];
      case 'views':
        return ['Bảng', 'Thẻ'];
      case 'form':
        return ['Thông tin chung', 'Liên hệ'];
      case 'disabled':
        return ['Thông tin chung', 'Hợp đồng'];
      case 'closable':
        return this.records();
      default:
        return ['Thông tin chung', 'Đơn hàng', 'Lịch sử'];
    }
  });
  readonly filtered = computed(() =>
    this.rows().filter(r => this.selected() === 0 || r.status === (this.selected() === 1 ? 'pending' : 'done'))
  );
  count(index: number): number {
    return this.rows().filter(r => index === 0 || r.status === (index === 1 ? 'pending' : 'done')).length;
  }
  complete(): void {
    const first = this.rows().find(r => r.status === 'pending');
    if (first) this.rows.update(rows => rows.map(r => (r.id === first.id ? { ...r, status: 'done' } : r)));
  }
  async load(): Promise<void> {
    if (this.loading()) return;
    this.loading.set(true);
    await new Promise(resolve => setTimeout(resolve, 1000 + Math.random() * 1000));
    this.loading.set(false);
  }
  change(index: number): void {
    this.selected.set(index);
    if (this.variant() === 'loading') void this.load();
  }
  async save(): Promise<void> {
    if (!(this.name ?? '').trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.email ?? '')) {
      this.selected.set(!(this.name ?? '').trim() ? 0 : 1);
      this.notify.warning('Nhập tên khách hàng và email hợp lệ.');
      return;
    }
    await this.load();
    this.notify.success('Đã lưu thông tin khách hàng.');
  }
  beforeClose(code: string): () => boolean {
    return () => this.recordDrafts[code] === this.names[code] || window.confirm('Thông tin chưa lưu. Đóng tab này?');
  }
  close(code: string): void {
    this.recordDrafts[code] = this.names[code];
    this.records.update(rows => rows.filter(r => r !== code));
    this.selected.set(0);
  }
  reopen(): void {
    this.records.set(['CUS-001', 'CUS-002', 'CUS-003']);
  }
}

